function teEditarInformante(cod){
  const l=_teLinks.find(x=>x.codigo===cod); if(!l||!l.resposta) return;
  const inf=l.resposta.informante||{};
  const nome=prompt('Nome de quem respondeu:',inf.nome||''); if(nome===null) return;
  const rel=prompt('Relação / papel (ex.: Mãe, Pai, Pais, Professor(a)):',inf.relacao||l.respondente||''); if(rel===null) return;
  const n=nome.trim(), r=rel.trim()||l.respondente||'';
  teFs().collection('testes_links').doc(cod).update({'resposta.informante.nome':n,'resposta.informante.relacao':r,respondente:r})
    .then(()=>{ l.resposta.informante=Object.assign({},inf,{nome:n,relacao:r}); l.respondente=r; toast('Informante atualizado ✅'); teRenderFicha(); })
    .catch(e=>toast('Não foi possível salvar: '+(e&&e.code||'erro')));
}
